class Solution:
    def solve(self, n: int, m: int, offers: List[tuple]) -> List[int]:
        """
        Process offers for each x from 1 to n.
        Returns list of total occupied days for each x.
        """
        ans = [0] * (n + 1)

        for x in range(1, n + 1):
            occupied = [False] * (n + 2)  # 1-indexed, +2 for safety
            count = 0

            for l, r in offers:
                length = r - l + 1

                # Condition 1: minimum length requirement
                if length < x:
                    continue

                # Condition 2: check if any day in [l, r] is already occupied
                conflict = False
                for day in range(l, r + 1):
                    if occupied[day]:
                        conflict = True
                        break

                if conflict:
                    continue

                # Accept the offer
                for day in range(l, r + 1):
                    occupied[day] = True

                count += length

            ans[x] = count

        return ans[1:]

