def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ""

    n = int(lines[0])
    intervals = []
    for i in range(n):
        parts = lines[i+1].split()
        l, r = int(parts[0]), int(parts[1])
        intervals.append((l, r, i))

    # Union-Find for connected components
    parent = list(range(n))
    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py

    # Build components based on interval overlap
    for i in range(n):
        for j in range(i+1, n):
            l1, r1 = intervals[i][0], intervals[i][1]
            l2, r2 = intervals[j][0], intervals[j][1]
            # Two intervals overlap if max(l1, l2) <= min(r1, r2)
            if max(l1, l2) <= min(r1, r2):
                union(i, j)

    # Group sheep by component
    comp = defaultdict(list)
    for i in range(n):
        comp[find(i)].append(i)

    # For each component, sort by l value and extend to result
    result = []
    for i in range(n):
        if comp[i]:
            comp[i].sort(key=lambda x: intervals[x][0])
            result.extend(comp[i])

    return ' '.join(map(str, result)) + '\n'

