        while power > 0:
            if power % 2 == 1:
                result = mat_mul(result, A)
            A = mat_mul(A, A)
            power //= 2
        return result

    def modpow(base, exp):
        res = 1
        base %= mod
        while exp > 0:
            if exp % 2 == 1:
                res = (res * base) % mod
            base = (base * base) % mod
            exp //= 2
        return res

