    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    edges = []
    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        edges.append((u - 1, v - 1))  # 0-indexed

    # Check if two edges cross
    def cross(a, b):
        """Check if edges with endpoints a and b cross"""
        u1, v1 = a
        u2, v2 = b
        # Normalize so u1 < v1, u2 < v2
        if u1 > v1:
            u1, v1 = v1, u1
        if u2 > v2:
            u2, v2 = v2, u2

        # Edges cross if endpoints alternate: a < c < b < d
        # where edges are (a,b) and (c,d) with a<b, c<d
        if u1 == u2 or v1 == u2 or u1 == v2 or v1 == v2:
            return False
        return (u1 < u2 < v1 < v2) or (u2 < u1 < v2 < v1)

    # Build crossing graph constraints
    crossing = [[False] * m for _ in range(m)]
    for i in range(m):
        for j in range(i + 1, m):
            if cross(edges[i], edges[j]):
                crossing[i][j] = crossing[j][i] = True

    # 2-SAT: For crossing edges (i,j), we need exactly one inside and one outside
    # Using implication graph with 2*m variables
    # variable 2*i: edge i is inside
    # variable 2*i+1: edge i is outside

    n_var = 2 * m
    adj = [[] for _ in range(n_var)]

    def build_clauses(i, j):
        """For crossing edges i and j, build implications"""
        # If i is inside, j must be outside: 2i -> 2j+1
        adj[2*i].append(2*j + 1)
        # If i is outside, j must be inside: 2i+1 -> 2j
        adj[2*i + 1].append(2*j)
        # If j is inside, i must be outside: 2j -> 2i+1
        adj[2*j].append(2*i + 1)
        # If j is outside, i must be inside: 2j+1 -> 2i
        adj[2*j + 1].append(2*i)

    for i in range(m):
        for j in range(i + 1, m):
            if crossing[i][j]:
                build_clauses(i, j)

    # Kosaraju's algorithm for SCC
    visited = [False] * n_var
    order = []

    def dfs1(v):
        visited[v] = True
        for w in adj[v]:
            if not visited[w]:
                dfs1(w)
        order.append(v)

    for i in range(n_var):
        if not visited[i]:
            dfs1(i)

    radj = [[] for _ in range(n_var)]
    for i in range(n_var):
        for w in adj[i]:
            radj[w].append(i)

    visited = [False] * n_var
    scc_id = [-1] * n_var
    scc_count = 0

    def dfs2(v, sid):
        visited[v] = True
        scc_id[v] = sid
        for w in radj[v]:
            if not visited[w]:
                dfs2(w, sid)

    for v in reversed(order):
        if not visited[v]:
            dfs2(v, scc_count)
            scc_count += 1

    # Check for unsatisfiable
    for i in range(m):
        if scc_id[2*i] == scc_id[2*i + 1]:
            return "Impossible"

    # Build assignment
    scc_index = [-1] * n_var
    for i in range(n_var):
        if scc_id[i] not in scc_index:
            scc_index[scc_id[i]] = len(scc_index)

    # Greedy: prefer inside when possible
    result = [''] * m
    for i in range(m):
        # If 2*i (inside) component comes before 2*i+1 (outside) in topological order,
        # prefer inside
        if scc_index[scc_id[2*i]] < scc_index[scc_id[2*i + 1]]:
            result[i] = 'i'
        else:
            result[i] = 'o'

    return ''.join(result) + '\n'

