from collections import defaultdict

def solution(input_str):
    data = input_str.strip().split('\n')
    if not data:
        return ""

    t = int(data[0])
    idx = 1
    results = []

    for _ in range(t):
        n = int(data[idx])
        idx += 1
        A = data[idx]
        idx += 1
        B = data[idx]
        idx += 1

        # Build the directed graph: u -> v means characters with original letter u
        # need to eventually become letter v (at some position)
        adj = defaultdict(set)

        for i in range(n):
            if A[i] != B[i]:
                u = ord(A[i]) - ord('a')
                v = ord(B[i]) - ord('a')
                adj[u].add(v)

        memo = {}
        visiting = set()

        def longest_path(u):
            """Find the longest path starting from u in the dependency graph.
            Returns -1 if a cycle is detected."""
            if u in visiting:
                return -1
            if u in memo:
                return memo[u]

            visiting.add(u)
            max_child = 0
            if u in adj and adj[u]:
                for v in adj[u]:
                    res = longest_path(v)
                    if res == -1:
                        visiting.remove(u)
                        return -1
                    max_child = max(max_child, res)
            visiting.remove(u)

            memo[u] = max_child + 1
            return memo[u]

        ans = 0
        for u in range(20):
            if u in adj:
                res = longest_path(u)
                if res > 0:
                    ans = max(ans, res)

        results.append(str(ans))

    return '\n'.join(results)

