def solution(input_str):
    lines = input_str.strip().split('\n')
    n, a, b = map(int, lines[0].split())
    ai = list(map(int, lines[1].split()))

    ans = float('inf')

    def get_prime_factors(x):
        """Get all distinct prime factors of x"""
        factors = set()
        d = 2
        while d * d <= x:
            while x % d == 0:
                factors.add(d)
                x //= d
            d += 1
        if x > 1:
            factors.add(x)
        return factors

    # Collect all prime factors from array elements
    all_primes = set()
    for x in ai:
        all_primes.update(get_prime_factors(x))

    if not all_primes:
        return str(0)

    def calc_cost(p):
        """Calculate minimum cost for prime p"""
        must_remove = []  # Indices that can't be fixed
        can_change = []   # Indices that can be changed by ±1

        for i, x in enumerate(ai):
            if x % p == 0:
                continue  # Already divisible
            elif (x - 1) % p == 0 or (x + 1) % p == 0:
                can_change.append(i)
            else:
                must_remove.append(i)

        # If nothing must be removed, just change all candidates
        if not must_remove:
            return len(can_change) * b

        # Must remove - find the smallest segment [first, last] containing all must_remove
        must_remove.sort()
        first = must_remove[0]
        last = must_remove[-1]

        # Cost to remove the segment
        cost_remove = (last - first + 1) * a

        # Cost to change remaining can_change elements (those outside [first, last])
        cost_change = 0
        for idx in can_change:
            if idx < first or idx > last:
                cost_change += b

        return cost_remove + cost_change

    if not all_primes:
        # Edge case: no prime factors found (shouldn't happen per constraints)
        return str(0)

    # Try each prime and find minimum cost
    for p in all_primes:
        cost = calc_cost(p)
        ans = min(ans, cost)

    return str(int(ans))

