                points.append((x, y))

    # Focus on extreme/boundary points
    extreme_points = []
    for x in range(-r, r + 1):
        for y in range(-r, r + 1):
            if x*x + y*y == r*r:
                extreme_points.append((x, y))
    # Also include axis extremes (may be more points)
    for x in [(-r, 0), (r, 0)]:
        if len(points) == 0 or x in points:
            if not any(p[0] == x[0] and p[1] == x[1] for p in extreme_points):
                extreme_points.append(x)

    extreme = extreme_points
    candidates = extreme if extreme else points

    best_score = -1
    best_config = None

    # Use deterministic seeding for reproducibility
    def find_optimal():
        max_iter = 5000

        for seed_offset in range(100):
            random.seed(hash(input_str) + seed_offset)

            # Greedy initialization starting from corner
            def greedy_init():
                if len(candidates) == 0:
                    return [points[0]] * n if points else [(0,0)] * n

                sorted_candidates = sorted(candidates, 
                    key=lambda p: p[0]**2 + p[1]**2, reverse=True)

                config = [sorted_candidates[0]] * n

                def score(c):
                    s = 0
                    for i in range(len(c)):
                        for j in range(i + 1, len(c)):
                            s += dist_sq(c[i], c[j])
                    return s

                for i in range(n):
                    best_p = sorted_candidates[0]
                    best_s = score(config + [best_p]) - score(config)

                    for p in sorted_candidates:
                        s = score(config + [p]) - score(config)
                        if s > best_s:
                            best_s = s
                            best_p = p
                    config = config[:-1] + [p]

                return config

            config = greedy_init()
            score = compute_total(config)

            if score > best_score:
                best_score = score
                best_config = tuple(config)

            # Local search
            rng = random.seed(hash(input_str) + seed_offset)
            for _ in range(min(100, len(candidates) * n)):
                improved = False
                for i in range(n):
                    try:
                        others = [c for j, c in enumerate(config) if j != i]
                        other = random.choice(others) if others else candidates[0]
                        new_config = list(config)
                        new_config[i] = other
                        s = compute_total(new_config)
                        if s > score:
                            config = new_config
                            score = s
                            best_score = max(best_score, score)
                            best_config = tuple(config)
                            improved = True
                    except:
                        continue
                    if improved:
                        break

            random.seed(hash(input_str) + seed_offset)
            # Random restart
            for _ in range(5):
                local_config = [random.choice(candidates) for _ in range(n)]
                local_score = compute_total(local_config)
                if local_score > best_score:
                    best_score = local_score
                    best_config = tuple(local_config)

        return best_score, best_config

    best_score, best_config = find_optimal()

    # Convert points to strings for output
    output_lines = [str(best_score)]
    for x, y in best_config:
        output_lines.append(f"{x} {y}")

    return "\n".join(output_lines)

