def solution(input_data):
    lines = input_data.strip().split('\n')
    n, m = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    for line in lines[1:-1] if len(lines) > 1 else []:
        u, v = map(int, line.split())
        adj[u].append(v)
        adj[v].append(u)

    k = math.ceil(math.sqrt(n))

    visited = [False] * (n + 1)
    depth = [0] * (n + 1)
    parent = [0] * (n + 1)

    def dfs(u, p, d):
        visited[u] = True
        depth[u] = d
        cycle = None

        for v in adj[u]:
            if v == p:
                continue
            if visited[v]:
                if depth[v] > 0:
                    cycle_len = d - depth[v] + 1
                    if cycle_len >= k:
                        cik = []
                        curr = v
                        while True:
                            cik.append(curr)
                            curr = parent[curr]
                            if curr == u:
                                break
                        cik.append(u)
                        if cik is None:
                            return cik
                        else:
                            cycle = cik
            else:
                parent[v] = u
                res = dfs(v, u, d + 1)
                if res:
                    if res is None:
                        cycle = cik if res is not None else None
                    else:
                        cycle = res
        return cycle

    result_cycle = dfs(1, 0, 1)

    if result_cycle:
        output = f"2\n{len(result_cycle)}\n" + " ".join(map(str, result_cycle))
        return output.strip()

    # Build independent set using greedy approach
    visited2 = [False] * (n + 1)
    iset = []

    for u in range(1, n + 1):
        if visited2[u]:
            continue

        valid = True
        for v in adj[u]:
            if not visited2[v] and v in iset:
                valid = False
                break

        if valid:
            iset.append(u)
            for v in adj[u]:
                visited2[v] = True

    result_iset = iset[:k]
    output = f"1\n" + " ".join(map(str, result_iset))
    return output.strip()

