def solution(input_string):
    try:
        N = int(input_string.strip())
    except:
        return "0\n"

    if N <= 0:
        return "0\n"

    # dr_count[d] = count of numbers in [1, N] with digital root d
    dr_count = [0] * 10
    full_cycles = N // 9
    rem = N % 9

    for d in range(1, 10):
        dr_count[d] = full_cycles

    for d in range(1, rem + 1):
        dr_count[d] += 1

    # Count all triples where d(A*B) = d(C)
    result = 0
    for A in range(1, N + 1):
        drA = (A - 1) % 9 + 1
        for B in range(1, N + 1):
            drB = (B - 1) % 9 + 1

            drAB = (drA * drB) % 9
            if drAB == 0:
                drAB = 9

            result += dr_count[drAB]

    # Subtract triples where A*B = C exactly
    # For each i, floor(N/i) counts how many C values are multiples of i
    exact = 0
    for i in range(1, N + 1):
        exact += N // i

    return str(result - exact) + '\n'
